"""Lists the commands of the Tapir Add-On with GetCommands and checks that a command exists before calling it."""
import aclib

commands = {command['name'] : command for command in aclib.RunTapirCommand ('GetCommands')['commands']}

if 'GetAddOnVersion' in commands:
    aclib.PrintJson (commands['GetAddOnVersion'])
    aclib.PrintJson (aclib.RunTapirCommand ('GetAddOnVersion'))

"""Asks the user to click a point in the current window with GetPointFromUser and prints it.

Waits for a click in Archicad; Escape cancels the input and the command fails. The optional
snapFilter makes the cursor snap only to the end points and reference lines of walls.
"""
import aclib

aclib.PrintJson (aclib.RunTapirCommand ('GetPointFromUser', {
    'prompt': 'Click a point on a wall',
    'snapFilter': {'base': 'None', 'include': ['Wall', 'WallOn']}
}))

"""Converts two model points to pixel positions of the current view window with ModelToScreen.

The pixels depend on the window's size, scale and zoom. Requires Archicad 29 or later.
"""
import aclib

aclib.PrintJson (aclib.RunTapirCommand ('ModelToScreen', {
    'coordinates': [
        {'x': 0.0, 'y': 0.0, 'z': 0.0},
        {'x': 5.0, 'y': 3.0, 'z': 0.0}
    ]
}))

"""Converts two pixel positions of the current view window to model coordinates with ScreenToModel.

The result depends on the window's size, scale and zoom.
"""
import aclib

aclib.PrintJson (aclib.RunTapirCommand ('ScreenToModel', {
    'screenPoints': [
        {'h': 0, 'v': 0},
        {'h': 200, 'v': 100}
    ]
}))

"""Asks the user to click a wall or a column with GetElementFromUser and prints its id, type and the clicked point.

Waits for a click in Archicad; Escape returns cancelled. The optional snapFilter makes the cursor
snap only to the points and lines of walls and columns.
"""
import aclib

aclib.PrintJson (aclib.RunTapirCommand ('GetElementFromUser', {
    'prompt': 'Click a wall or a column',
    'elementTypes': ['Wall', 'Column'],
    'snapFilter': {'include': ['Wall', 'WallOn', 'Column', 'ColumnOn']}
}))

"""ConvertImages converts base64 encoded images with Archicad's own converters. The formats are Bitmap, GIF,
TIFF, JPEG and PNG, or the MIME type of another format Archicad can read or write. Here the PNG preview image
of an element is converted to JPEG, and to a MIME type format.
"""
import base64
import aclib

elements = aclib.RunTapirCommand ('GetAllElements')['elements']
if not elements:
    print ('No elements in the project.')
    raise SystemExit (0)

preview = aclib.RunTapirCommand ('GetElementPreviewImage', {
    'elementId': elements[0]['elementId'],
    'imageType': '3D',
    'format': 'png',
    'width': 128,
    'height': 128
})
if 'previewImage' not in preview:
    print ('No preview image: {}'.format (preview))
    raise SystemExit (0)

result = aclib.RunTapirCommand ('ConvertImages', {
    'images': [
        {'image': preview['previewImage'], 'inputFormat': 'PNG', 'outputFormat': 'JPEG'},
        {'image': preview['previewImage'], 'inputFormat': 'image/png', 'outputFormat': 'image/tiff'},
        {'image': 'bm90IGFuIGltYWdl', 'inputFormat': 'PNG', 'outputFormat': 'GIF'}
    ]
})

for converted in result['images']:
    if 'error' in converted:
        print ('Error: {}'.format (converted['error']['message']))
        continue
    data = base64.b64decode (converted['image'])
    print ('{} bytes, starting with {}'.format (len (data), data[:4]))

"""Opens the first layout, goes back to the floor plan and closes the layout's window with CloseWindows.

Needs at least one Layout. Requires Archicad 27 or later.
"""
import aclib

layouts = aclib.RunTapirCommand ('GetDatabases', {'types': ['Layout']})['databases']
if not layouts:
    raise SystemExit ('No layout in the project.')
layoutId = layouts[0]['databaseId']

aclib.RunTapirCommand ('ChangeWindow', {'databaseId': layoutId})
aclib.RunTapirCommand ('ChangeWindow', {'windowType': 'FloorPlan'})

aclib.PrintJson (aclib.RunTapirCommand ('CloseWindows', {
    'windows': [
        {'databaseId': layoutId, 'windowType': 'Layout'}
    ]
}))

"""Deletes the trace reference (ghost) of the first section with DeleteGhostRecords.

Needs at least one Section; one without a trace reference gets a failed result. Not undoable.
"""
import aclib

sections = aclib.RunTapirCommand ('GetDatabases', {'types': ['Section']})['databases'][:1]
if not sections:
    raise SystemExit ('No section in the project.')

aclib.PrintJson (aclib.RunTapirCommand ('DeleteGhostRecords', {
    'databases': [{'databaseId': sections[0]['databaseId']}]
}))

"""Prints the paths of Archicad's preferences, temporary and templates folders with GetSpecialFolders."""
import aclib

aclib.PrintJson (aclib.RunTapirCommand ('GetSpecialFolders', {
    'folderTypes': ['ApplicationPrefs', 'Temporary', 'Templates']
}))

"""Sets the value of the first Project Info field with SetProjectInfoField, reads it back, then restores it."""
import aclib

field = aclib.RunTapirCommand ('GetProjectInfoFields')['fields'][0]

aclib.PrintJson (aclib.RunTapirCommand ('SetProjectInfoField', {
    'projectInfoId': field['projectInfoId'],
    'projectInfoValue': 'Set by Tapir'
}))
aclib.RunTapirCommand ('GetProjectInfoFields')

aclib.PrintJson (aclib.RunTapirCommand ('SetProjectInfoField', {
    'projectInfoId': field['projectInfoId'],
    'projectInfoValue': field['projectInfoValue']
}))

"""Creates a custom Project Info field with CreateProjectInfoFields, then deletes it again.

From Archicad 30 the new field goes to the first Project Info group unless projectInfoGroupId is given.
"""
import aclib

created = aclib.RunTapirCommand ('CreateProjectInfoFields', {
    'projectInfoFields': [
        {'projectInfoName': 'Tapir Example Field', 'projectInfoValue': 'Created by Tapir'}
    ]
})['fields'][0]
aclib.PrintJson (created)
if 'error' in created:
    raise SystemExit ('The field could not be created.')

aclib.RunTapirCommand ('GetProjectInfoFields')

if 'projectInfoFieldId' in created:
    aclib.RunTapirCommand ('DeleteProjectInfoFields', {'projectInfoFieldIds': [{'projectInfoFieldId': created['projectInfoFieldId']}]})
else:
    aclib.RunTapirCommand ('DeleteProjectInfoFields', {'projectInfoIds': [created['projectInfoId']]})

"""Creates a custom Project Info field and deletes it by its autotext key with DeleteProjectInfoFields.

Built-in fields cannot be deleted. From Archicad 30 fields can also be deleted by projectInfoFieldIds.
"""
import aclib

created = aclib.RunTapirCommand ('CreateProjectInfoFields', {
    'projectInfoFields': [{'projectInfoName': 'Tapir Field To Delete'}]
})['fields'][0]
if 'projectInfoId' not in created:
    raise SystemExit ('The field could not be created.')

aclib.PrintJson (aclib.RunTapirCommand ('DeleteProjectInfoFields', {'projectInfoIds': [created['projectInfoId']]}))

"""Creates a custom Project Info field, renames it with RenameProjectInfoFields, then deletes it.

Built-in fields cannot be renamed. Requires Archicad 30 or later.
"""
import aclib

created = aclib.RunTapirCommand ('CreateProjectInfoFields', {
    'projectInfoFields': [{'projectInfoName': 'Tapir Example Field'}]
})['fields'][0]
if 'projectInfoFieldId' not in created:
    raise SystemExit ('The field could not be created.')
fieldId = created['projectInfoFieldId']

aclib.PrintJson (aclib.RunTapirCommand ('RenameProjectInfoFields', {
    'projectInfoFields': [
        {'projectInfoFieldId': fieldId, 'name': 'Tapir Renamed Field'}
    ]
}))
aclib.RunTapirCommand ('GetProjectInfoGroups')

aclib.RunTapirCommand ('DeleteProjectInfoFields', {'projectInfoFieldIds': [{'projectInfoFieldId': fieldId}]})

"""Creates a Project Info group, renames it with RenameProjectInfoGroups, then deletes it.

Requires Archicad 30 or later.
"""
import aclib

created = aclib.RunTapirCommand ('CreateProjectInfoGroups', {
    'projectInfoGroups': [{'name': 'Tapir Example Group'}]
})['projectInfoGroupIdsOrErrors'][0]
if 'error' in created:
    raise SystemExit ('The group could not be created.')
groupId = created['projectInfoGroupId']

aclib.PrintJson (aclib.RunTapirCommand ('RenameProjectInfoGroups', {
    'projectInfoGroups': [
        {'projectInfoGroupId': groupId, 'name': 'Tapir Renamed Group'}
    ]
}))
aclib.RunTapirCommand ('GetProjectInfoGroups')

aclib.RunTapirCommand ('DeleteProjectInfoGroups', {'projectInfoGroups': [{'projectInfoGroupId': groupId}]})

"""Creates a Project Info group and deletes it with DeleteProjectInfoGroups.

A group that holds built-in fields cannot be deleted. Requires Archicad 30 or later.
"""
import aclib

created = aclib.RunTapirCommand ('CreateProjectInfoGroups', {
    'projectInfoGroups': [{'name': 'Tapir Group To Delete'}]
})['projectInfoGroupIdsOrErrors'][0]
if 'error' in created:
    raise SystemExit ('The group could not be created.')

aclib.PrintJson (aclib.RunTapirCommand ('DeleteProjectInfoGroups', {
    'projectInfoGroups': [
        {'projectInfoGroupId': created['projectInfoGroupId']}
    ]
}))

"""Creates a Project Info group, moves it before the first group with MoveProjectInfoGroups, then deletes it.

Without beforeProjectInfoGroupId a group moves to the end of the list. Requires Archicad 30 or later.
"""
import aclib

firstGroupId = aclib.RunTapirCommand ('GetProjectInfoGroups')['projectInfoGroups'][0]['projectInfoGroupId']

created = aclib.RunTapirCommand ('CreateProjectInfoGroups', {
    'projectInfoGroups': [{'name': 'Tapir Example Group'}]
})['projectInfoGroupIdsOrErrors'][0]
if 'error' in created:
    raise SystemExit ('The group could not be created.')
groupId = created['projectInfoGroupId']

aclib.PrintJson (aclib.RunTapirCommand ('MoveProjectInfoGroups', {
    'projectInfoGroups': [
        {'projectInfoGroupId': groupId, 'beforeProjectInfoGroupId': firstGroupId}
    ]
}))
aclib.RunTapirCommand ('GetProjectInfoGroups')

aclib.RunTapirCommand ('DeleteProjectInfoGroups', {'projectInfoGroups': [{'projectInfoGroupId': groupId}]})

"""Prints the keywords of the autotexts available in dimension notes with GetNoteAutoTextKeywords.

Requires Archicad 26 or later.
"""
import aclib

noteAutotexts = aclib.RunTapirCommand ('GetNoteAutotexts', {'noteOwnerType': 'Dimension'})['noteAutotexts']
if not noteAutotexts:
    raise SystemExit ('No note autotexts found.')

aclib.PrintJson (aclib.RunTapirCommand ('GetNoteAutoTextKeywords', {
    'autoTextIds': [a['autotextId'] for a in noteAutotexts]
}))

"""Saves the first wall as a module in the temp folder, creates a hotlink node from it with CreateHotlinkNodes, then deletes the node.

Needs at least one Wall.
"""
import os
import tempfile
import aclib

walls = aclib.RunCommand ('API.GetElementsByType', {'elementType': 'Wall'})['elements'][:1]
if not walls:
    raise SystemExit ('No wall in the project.')
modulePath = os.path.join (tempfile.mkdtemp (), 'TapirExample.mod')
aclib.RunTapirCommand ('SaveAsModuleFile', {'moduleFilePath': modulePath, 'elements': walls})

node = aclib.RunTapirCommand ('CreateHotlinkNodes', {
    'hotlinkNodes': [
        {'sourceLocation': modulePath, 'name': 'Tapir Example', 'storyRangeType': 'AllStories'}
    ]
})['hotlinkNodes'][0]
aclib.PrintJson (node)

if 'hotlinkNodeId' in node:
    aclib.RunTapirCommand ('DeleteHotlinkNodes', {'hotlinkNodes': [{'hotlinkNodeId': node['hotlinkNodeId']}]})

"""Moves the first placed hotlink instance 1 m along x with ChangeHotlinkInstances, then moves it back.

Needs at least one placed Hotlink.
"""
import aclib

instances = aclib.RunCommand ('API.GetElementsByType', {'elementType': 'Hotlink'})['elements'][:1]
if not instances:
    raise SystemExit ('No placed hotlink in the project.')

details = aclib.RunTapirCommand ('GetDetailsOfElements', {'elements': instances})['detailsOfElements'][0]['details']
origin = details['origin']

aclib.PrintJson (aclib.RunTapirCommand ('ChangeHotlinkInstances', {
    'hotlinkInstances': [{
        'elementId': instances[0]['elementId'],
        'origin': {'x': origin['x'] + 1.0, 'y': origin['y'], 'z': origin['z']}
    }]
}))

aclib.PrintJson (aclib.RunTapirCommand ('ChangeHotlinkInstances', {
    'hotlinkInstances': [{
        'elementId': instances[0]['elementId'],
        'origin': origin,
        'rotationAngle': details['rotationAngle'],
        'mirrored': details['mirrored']
    }]
}))

"""Re-reads the source files of every top-level hotlink node with UpdateHotlinks, as the Hotlink Manager's Update does.

Needs at least one hotlink.
"""
import aclib

hotlinks = aclib.RunTapirCommand ('GetHotlinks')['hotlinks']
if not hotlinks:
    raise SystemExit ('No hotlink in the project.')

aclib.PrintJson (aclib.RunTapirCommand ('UpdateHotlinks', {
    'hotlinkNodes': [{'hotlinkNodeId': h['hotlinkNodeId']} for h in hotlinks]
}))

"""Prints whether the source file of each top-level hotlink is available, with GetHotlinkSourceStatus.

Needs at least one hotlink. Requires Archicad 27 or later.
"""
import aclib

hotlinks = aclib.RunTapirCommand ('GetHotlinks')['hotlinks']
if not hotlinks:
    raise SystemExit ('No hotlink in the project.')

aclib.PrintJson (aclib.RunTapirCommand ('GetHotlinkSourceStatus', {
    'hotlinks': [{'location': h['location']} for h in hotlinks]
}))

"""Sets the working length unit to millimeters and the floor plan cut plane height to 1.2 m with SetProjectPreferences, then restores both.

Only the given fields change. In Teamwork the PreferencesDialog lockable object set must be reserved first.
Requires Archicad 27 or later.
"""
import aclib

original = aclib.RunTapirCommand ('GetProjectPreferences', {'preferenceTypes': ['WorkingUnits', 'FloorPlanCutPlane']})

aclib.PrintJson (aclib.RunTapirCommand ('SetProjectPreferences', {
    'workingUnits': {
        'length': {'unit': 'Millimeter', 'decimals': 0}
    },
    'floorPlanCutPlane': {
        'cutPlaneHeight': 1.2
    }
}))
aclib.RunTapirCommand ('GetProjectPreferences', {'preferenceTypes': ['WorkingUnits', 'FloorPlanCutPlane']})

aclib.PrintJson (aclib.RunTapirCommand ('SetProjectPreferences', {
    'workingUnits': original['workingUnits'],
    'floorPlanCutPlane': original['floorPlanCutPlane']
}))

"""Formats a length, an area and an angle as Archicad shows them in the project's units, with ConvertUnitValues.

Values are given in meters, square meters and radians. Requires Archicad 27 or later.
"""
import math
import aclib

aclib.PrintJson (aclib.RunTapirCommand ('ConvertUnitValues', {
    'values': [
        {'value': 1.2345, 'preference': 'WorkModel'},
        {'value': 12.5, 'preference': 'CalcArea'},
        {'value': math.pi / 4, 'preference': 'WorkAngle'}
    ]
}))

"""Sets the project's longitude, latitude and altitude with SetGeoLocation, reads them back, then restores them.

Omitted fields stay unchanged.
"""
import aclib

original = aclib.RunTapirCommand ('GetGeoLocation')['projectLocation']

aclib.PrintJson (aclib.RunTapirCommand ('SetGeoLocation', {
    'projectLocation': {
        'longitude': 19.04,
        'latitude': 47.50,
        'altitude': 110.0
    }
}))
aclib.RunTapirCommand ('GetGeoLocation')

aclib.PrintJson (aclib.RunTapirCommand ('SetGeoLocation', {
    'projectLocation': {
        'longitude': original['longitude'],
        'latitude': original['latitude'],
        'altitude': original['altitude']
    }
}))

"""Sets the project date and time to noon on 21 June with SetPlaceSettings, prints the sun position, then restores them.

Only the given fields change; an empty placeInfo only reads the settings. Requires Archicad 27 or later.
"""
import aclib

original = aclib.RunTapirCommand ('SetPlaceSettings', {'placeInfo': {}})['placeInfo']
aclib.PrintJson (original)

aclib.PrintJson (aclib.RunTapirCommand ('SetPlaceSettings', {
    'placeInfo': {'month': 6, 'day': 21, 'hour': 12, 'minute': 0, 'second': 0}
}))

aclib.PrintJson (aclib.RunTapirCommand ('SetPlaceSettings', {
    'placeInfo': {key: original[key] for key in ['year', 'month', 'day', 'hour', 'minute', 'second', 'sumTime']}
}))

"""Calculates the sun's azimuth and altitude at noon on 21 June at the project location with CalculateSunPosition.

Fields left out keep the project's value. The project is not changed.
"""
import aclib

aclib.PrintJson (aclib.RunTapirCommand ('CalculateSunPosition', {
    'dateTime': {'month': 6, 'day': 21, 'hour': 12, 'minute': 0, 'second': 0}
}))

"""Stores a key-value pair on the first wall with SetElementUserData, reads it back, then removes it.

The data is saved with the project, invisible in the Archicad UI. Needs at least one Wall.
"""
import aclib

walls = aclib.RunCommand ('API.GetElementsByType', {'elementType': 'Wall'})['elements'][:1]
if not walls:
    raise SystemExit ('No wall in the project.')
wallId = walls[0]['elementId']

aclib.PrintJson (aclib.RunTapirCommand ('SetElementUserData', {
    'elementUserData': [
        {'elementId': wallId, 'userData': [{'key': 'tapir-example.externalId', 'value': 'W-001'}]}
    ]
}))
aclib.RunTapirCommand ('GetElementUserData', {'elements': walls})

aclib.PrintJson (aclib.RunTapirCommand ('SetElementUserData', {
    'elementUserData': [
        {'elementId': wallId, 'keysToDelete': ['tapir-example.externalId']}
    ]
}))

"""Draws a 10 x 10 m rectangle marquee around the origin with SetMarquee, then reads it back.

The original marquee (or no marquee) is restored at the end.
"""
import aclib

original = aclib.RunTapirCommand ('GetMarquee', {})

aclib.PrintJson (aclib.RunTapirCommand ('SetMarquee', {
    'box': {'xMin': -5.0, 'yMin': -5.0, 'xMax': 5.0, 'yMax': 5.0},
    'multiStory': False
}))
aclib.RunTapirCommand ('GetMarquee', {})

# Restore the original marquee; without polygon and box SetMarquee removes it.
if original['type'] == 'none':
    aclib.RunTapirCommand ('SetMarquee', {})
elif original['type'] == 'polygon':
    aclib.RunTapirCommand ('SetMarquee', {'polygon': original['polygon'], 'multiStory': original['multiStory']})
else:
    aclib.RunTapirCommand ('SetMarquee', {
        'box': original['box'],
        'rotationAngle': original.get ('rotationAngle', 0.0),
        'multiStory': original['multiStory']
    })

"""Finds walls by story and by a property value with GetElementsByCriteria, first counting them only.

The property criterion compares the wall thickness in metres, whatever the project's display units.
"""
import aclib

aclib.PrintJson (aclib.RunTapirCommand ('GetElementsByCriteria', {'types': ['Wall'], 'countOnly': True}))

aclib.PrintJson (aclib.RunTapirCommand ('GetElementsByCriteria', {
    'types': ['Wall'],
    'floorIndices': [0],
    'limit': 5
}))

thickness = aclib.RunCommand ('API.GetPropertyIds', {
    'properties': [{'type': 'BuiltIn', 'nonLocalizedName': 'General_Thickness'}]
})['properties'][0]['propertyId']

aclib.PrintJson (aclib.RunTapirCommand ('GetElementsByCriteria', {
    'types': ['Wall'],
    'propertyCriteria': [{'propertyId': thickness, 'operator': 'greaterThan', 'value': '0.2'}],
    'limit': 5
}))

"""Changes the Element ID of a wall with SetElementInfoStrings, reads it back, then restores it.

Needs at least one editable Wall.
"""
import aclib

walls = aclib.RunTapirCommand ('GetElementsByType', {'elementType': 'Wall', 'filters': ['IsEditable']})['elements'][:1]
if not walls:
    raise SystemExit ('No editable wall in the project.')
wallId = walls[0]['elementId']

def GetElementId ():
    return aclib.RunTapirCommand ('GetDetailsOfElements', {'elements': walls, 'fields': ['id']})['detailsOfElements'][0]['id']

originalId = GetElementId ()

aclib.PrintJson (aclib.RunTapirCommand ('SetElementInfoStrings', {
    'elements': [{'elementId': wallId, 'infoString': 'TAPIR-EXAMPLE'}]
}))
print ('Element ID: {} -> {}'.format (originalId, GetElementId ()))

aclib.RunTapirCommand ('SetElementInfoStrings', {
    'elements': [{'elementId': wallId, 'infoString': originalId}]
})

"""Reads the category values new walls, slabs and columns get from their tool defaults, with GetCategoryValuesOfDefaults."""
import aclib

aclib.PrintJson (aclib.RunTapirCommand ('GetCategoryValuesOfDefaults', {
    'elementTypes': ['Wall', 'Slab', 'Column'],
    'categories': ['StructuralFunction', 'Position', 'RenovationStatus']
}))

"""Changes the Structural Function of a wall with SetCategoryValuesOfElements, reads it back, then restores it.

Needs at least one editable Wall.
"""
import aclib

walls = aclib.RunTapirCommand ('GetElementsByType', {'elementType': 'Wall', 'filters': ['IsEditable']})['elements'][:1]
if not walls:
    raise SystemExit ('No editable wall in the project.')
wallId = walls[0]['elementId']

def GetStructuralFunction ():
    result = aclib.RunTapirCommand ('GetCategoryValuesOfElements', {'elements': walls, 'categories': ['StructuralFunction']})
    return result['categoryValuesOfElements'][0]['categoryValues'][0]

categories = aclib.RunTapirCommand ('GetElementCategories', {})['categories']
structuralFunction = next (category for category in categories if category['type'] == 'StructuralFunction')
original = GetStructuralFunction ()
newValue = next (value for value in structuralFunction['values']
                 if value['isVisibleOnUI'] and value['categoryValueId'] != original['categoryValueId'])

aclib.PrintJson (aclib.RunTapirCommand ('SetCategoryValuesOfElements', {
    'elementCategoryValues': [{'elementId': wallId, 'type': 'StructuralFunction', 'categoryValueId': newValue['categoryValueId']}]
}))
print ('Structural Function: {} -> {}'.format (original['name'], GetStructuralFunction ()['name']))

aclib.RunTapirCommand ('SetCategoryValuesOfElements', {
    'elementCategoryValues': [{'elementId': wallId, 'type': 'StructuralFunction', 'categoryValueId': original['categoryValueId']}]
})

"""Converts a reveal depth offset of 0 measured from the wall's core skin to the wall side reference with ConvertRevealOffsets.

Needs at least one Window or Door placed in a wall. Requires Archicad 27 or later.
"""
import aclib

openings = []
for elementType in ['Window', 'Door']:
    openings += aclib.RunTapirCommand ('GetElementsByType', {'elementType': elementType})['elements']
if not openings:
    raise SystemExit ('No window or door in the project.')

aclib.PrintJson (aclib.RunTapirCommand ('ConvertRevealOffsets', {
    'openings': [{'elementId': opening['elementId'], 'coreOffset': 0.0} for opening in openings[:3]]
}))

"""Cuts the first walls with a horizontal plane 1 m above project zero with GetCutPolygonsOfElements.

Returns the building material, cut area and cut polygons of each body. Needs at least one Wall. On Archicad 25-27
the building materials are left out.
"""
import aclib

walls = aclib.RunTapirCommand ('GetElementsByType', {'elementType': 'Wall'})['elements'][:3]
if not walls:
    raise SystemExit ('No wall in the project.')

aclib.PrintJson (aclib.RunTapirCommand ('GetCutPolygonsOfElements', {
    'elements': walls,
    'cutPlane': {
        'basePoint': {'x': 0.0, 'y': 0.0, 'z': 1.0},
        'axisX': {'x': 1.0, 'y': 0.0, 'z': 0.0},
        'axisY': {'x': 0.0, 'y': 1.0, 'z': 0.0},
        'axisZ': {'x': 0.0, 'y': 0.0, 'z': 1.0}
    }
}))

"""Links the first wall to the second one with LinkElements, reads the link back, then removes it.

Scripts can record their own relations between elements this way. Needs at least two Walls.
"""
import aclib

walls = aclib.RunTapirCommand ('GetElementsByType', {'elementType': 'Wall'})['elements'][:2]
if len (walls) < 2:
    raise SystemExit ('Fewer than two walls in the project.')

# flags is a 32-bit integer free for the script's own use.
aclib.PrintJson (aclib.RunTapirCommand ('LinkElements', {
    'links': [{'fromElementId': walls[0]['elementId'], 'toElementId': walls[1]['elementId'], 'flags': 1}]
}))
aclib.RunTapirCommand ('GetLinksOfElements', {'elements': walls[:1]})

aclib.RunTapirCommand ('UnlinkElements', {
    'links': [{'fromElementId': walls[0]['elementId'], 'toElementId': walls[1]['elementId']}]
})

"""Switches the link by criteria of property objects on or off for a wall with SetLinkedPropertyObjectsOfElements, reads it back, then restores it.

Needs at least one editable Wall.
"""
import aclib

walls = aclib.RunTapirCommand ('GetElementsByType', {'elementType': 'Wall', 'filters': ['IsEditable']})['elements'][:1]
if not walls:
    raise SystemExit ('No editable wall in the project.')
wallId = walls[0]['elementId']

def GetLinkByCriteria ():
    linked = aclib.RunTapirCommand ('GetLinkedPropertyObjectsOfElements', {'elements': walls})
    return linked['linkedPropertyObjectsOfElements'][0]['linkByCriteria']

original = GetLinkByCriteria ()

aclib.PrintJson (aclib.RunTapirCommand ('SetLinkedPropertyObjectsOfElements', {
    'elementsWithLinkedPropertyObjects': [{'elementId': wallId, 'linkByCriteria': not original}]
}))
print ('Link by criteria: {} -> {}'.format (original, GetLinkByCriteria ()))

aclib.RunTapirCommand ('SetLinkedPropertyObjectsOfElements', {
    'elementsWithLinkedPropertyObjects': [{'elementId': wallId, 'linkByCriteria': original}]
})

"""Finds the walls that collide with columns or beams with GetCollisions.

Needs Walls and Columns or Beams.
"""
import aclib

walls = aclib.RunTapirCommand ('GetElementsByType', {'elementType': 'Wall'})['elements']
others = []
for elementType in ['Column', 'Beam']:
    others += aclib.RunTapirCommand ('GetElementsByType', {'elementType': elementType})['elements']
if not walls or not others:
    raise SystemExit ('No walls, or no columns or beams in the project.')

