    'splinesData': [
        {'coordinates': fitPoints}
    ]
})['elements']
spline = created[0]['elementId']

aclib.PrintJson (aclib.RunTapirCommand ('GetSplineMaxDistances', {
    'splines': [
        {
            'elementId': spline,
            'segmentIndex': 0,
            'coordinates': [{'x': 1.0, 'y': 0.5}]
        },
        {
            'elementId': spline,
            'segmentIndex': 10,
            'coordinates': [{'x': 1.0, 'y': 0.5}]
        }
    ]
}))

aclib.RunTapirCommand ('DeleteElements', {
    'elements': [{'elementId': spline}]
})

