})

aclib.PrintJson (aclib.RunTapirCommand ('DeleteModulData', {
    'names': ['tapir-example/delete', 'tapir-example/missing']
}))

aclib.RunTapirCommand ('GetModulData', {
    'names': ['tapir-example/delete']
})

