"""Subtracts a small box morph from a bigger one with CreateSolidOperations.

Both morphs are created by the script and replaced by the resulting morph, which is deleted at the end.
"""
import aclib

def BoxBody (sizeX, sizeY, sizeZ):
    return {
        'bodyType': 'Solid',
        'vertices': [
            {'x': 0, 'y': 0, 'z': 0}, {'x': sizeX, 'y': 0, 'z': 0}, {'x': sizeX, 'y': sizeY, 'z': 0}, {'x': 0, 'y': sizeY, 'z': 0},
            {'x': 0, 'y': 0, 'z': sizeZ}, {'x': sizeX, 'y': 0, 'z': sizeZ}, {'x': sizeX, 'y': sizeY, 'z': sizeZ}, {'x': 0, 'y': sizeY, 'z': sizeZ}
        ],
        'polygons': [
            {'vertexIds': [0, 3, 2, 1]}, {'vertexIds': [4, 5, 6, 7]}, {'vertexIds': [0, 1, 5, 4]},
            {'vertexIds': [1, 2, 6, 5]}, {'vertexIds': [2, 3, 7, 6]}, {'vertexIds': [3, 0, 4, 7]}
        ]
    }

morphs = aclib.RunTapirCommand ('CreateMorphs', {
    'morphsData': [
        {'basePoint': {'x': 0.0, 'y': 0.0, 'z': 0.0}, 'body': BoxBody (2.0, 2.0, 1.0)},
        {'basePoint': {'x': 0.5, 'y': 0.5, 'z': 0.5}, 'body': BoxBody (1.0, 1.0, 1.0)}
    ]
})['elements']

result = aclib.RunTapirCommand ('CreateSolidOperations', {
    'operations': [{'targetId': morphs[0]['elementId'], 'operatorId': morphs[1]['elementId'], 'operation': 'Subtraction'}]
})['results'][0]
aclib.PrintJson (result)

if 'elements' in result:
    aclib.RunTapirCommand ('DeleteElements', {'elements': result['elements']})

"""Removes the merge between two slabs with UnmergeElements.

The slabs are created and merged by the script first, and deleted at the end.
"""
import aclib

# Two adjacent slabs, created by this script and deleted at the end.
slabs = aclib.RunTapirCommand ('CreateSlabs', {
    'slabsData': [
        {'level': 0.0, 'thickness': 0.3, 'polygonCoordinates': [{'x': 50.0, 'y': 50.0}, {'x': 54.0, 'y': 50.0}, {'x': 54.0, 'y': 54.0}, {'x': 50.0, 'y': 54.0}]},
        {'level': 0.0, 'thickness': 0.3, 'polygonCoordinates': [{'x': 54.0, 'y': 50.0}, {'x': 56.0, 'y': 50.0}, {'x': 56.0, 'y': 54.0}, {'x': 54.0, 'y': 54.0}]}
    ]
})['elements']

aclib.RunTapirCommand ('MergeElements', {'elements': slabs})

aclib.PrintJson (aclib.RunTapirCommand ('UnmergeElements', {
    'elementPairs': [{'elementId1': slabs[0]['elementId'], 'elementId2': slabs[1]['elementId']}]
}))

aclib.RunTapirCommand ('GetMergedElements', {'elements': slabs})

aclib.RunTapirCommand ('DeleteElements', {'elements': slabs})

"""Lets the user pick a door and set its parameters in Archicad's Door Settings dialog with PickLibraryPart.

The response holds the chosen library part and its GDL parameters with the values set in the dialog,
or cancelled when the user pressed Cancel. Nothing is placed in the project.
"""
import aclib

result = aclib.RunTapirCommand ('PickLibraryPart', {'elementType': 'Door'})
if result is not None:
    if result['cancelled']:
        print ('Cancelled.')
    else:
        print ('Library part: ' + result.get ('libPart', {}).get ('name', '(unknown)'))
        for parameter in result['parameters'][:10]:
            print ('  {} = {}'.format (parameter['name'], parameter.get ('value')))
